        if (e == NULL) {
            Entry fresh;
            strcpy(fresh.word, word);
            fresh.count = 0;
            if (!vector_push(&entries, &fresh)) {
                free(entries.data);
                return 1;
            }
            e = vector_at(&entries, entries.size - 1);
        }
        e->count++;
        if (best == NULL || e->count > best->count) {
            best = e;
        }
